dashboard.definition:
{
  "title": "KO Version",
  "description": "Audit and recover dashboards, reports and alerts by browsing version history captured in index=ko_history. (Dashboard Studio)",
  "defaults": {
    "tokens": {
      "default": {
        "koType": {
          "value": "*"
        },
        "ko_class": {
          "value": "dashboard"
        },
        "ko_realtype": {
          "value": ""
        },
        "link_title": {
          "value": "\u2013"
        },
        "link_app": {
          "value": "\u2013"
        },
        "time": {
          "value": ""
        },
        "compare_newer": {
          "value": "auto"
        },
        "compare_older": {
          "value": "auto"
        },
        "kpi_filter": {
          "value": "*"
        }
      }
    }
  },
  "expressions": {
    "conditions": {
      "cond_views": {
        "name": "type is views or all",
        "value": "$koType$ = \"views\" or $koType$ = \"*\""
      },
      "cond_reports": {
        "name": "type is reports and alerts",
        "value": "$koType$ = \"savedsearch\""
      },
      "cond_macros": {
        "name": "type is macros",
        "value": "$koType$ = \"macro\""
      },
      "cond_eventtypes": {
        "name": "type is event types",
        "value": "$koType$ = \"eventtype\""
      },
      "cond_fieldextractions": {
        "name": "type is field extractions",
        "value": "$koType$ = \"fieldextraction\""
      },
      "cond_lookups": {
        "name": "type is lookups",
        "value": "$koType$ = \"lookup\""
      },
      "cond_tags": {
        "name": "type is tags",
        "value": "$koType$ = \"tag\""
      },
      "cond_is_dashboard": {
        "name": "selected KO is a dashboard",
        "value": "$ko_realtype$ = \"views\""
      },
      "cond_is_savedsearch": {
        "name": "selected KO is a saved search",
        "value": "$ko_realtype$ = \"savedsearch\""
      },
      "cond_is_generic": {
        "name": "selected KO is generic - macro or event type",
        "value": "$ko_realtype$ != \"views\" and $ko_realtype$ != \"savedsearch\" and $ko_realtype$ != \"\""
      },
      "cond_is_not_dashboard": {
        "name": "selected KO is not a dashboard",
        "value": "$ko_realtype$ != \"views\" and $ko_realtype$ != \"\""
      },
      "cond_has_selection": {
        "name": "a KO is selected",
        "value": "$ko_realtype$ != \"\""
      },
      "cond_open_views": {
        "name": "open link type is views",
        "value": "$ko_realtype$ = \"views\""
      },
      "cond_open_savedsearch": {
        "name": "open link type is savedsearch",
        "value": "$ko_realtype$ = \"savedsearch\""
      },
      "cond_open_eventtype": {
        "name": "open link type is eventtype",
        "value": "$ko_realtype$ = \"eventtype\""
      },
      "cond_open_macro": {
        "name": "open link type is macro",
        "value": "$ko_realtype$ = \"macro\""
      },
      "cond_open_fieldextraction": {
        "name": "open link type is fieldextraction",
        "value": "$ko_realtype$ = \"fieldextraction\""
      },
      "cond_open_lookup": {
        "name": "open link type is lookup",
        "value": "$ko_realtype$ = \"lookup\""
      },
      "cond_open_tag": {
        "name": "open link type is tag",
        "value": "$ko_realtype$ = \"tag\""
      }
    }
  },
  "dataSources": {
    "ds_base": {
      "type": "ds.search",
      "name": "Base - KO version history",
      "options": {
        "query": "index=\"ko_history\" NOT source=\"ko_usage\"\n```WHAT: the one search every KO panel chains off. It unions the two event streams in this index, the periodic backup snapshots and the DELETE/MOVE audit records, then collapses them to ONE row per knowledge object carrying its full version history. Usage events are excluded here and joined separately.```\n| eval type=coalesce(type, case(match(source,\"views_delete_audit\"),\"views\",match(source,\"reports_and_alerts_delete_audit\"),\"savedsearch\",match(source,\"macros_delete_audit\"),\"macro\",match(source,\"eventtypes_delete_audit\"),\"eventtype\",match(source,\"fieldextractions_delete_audit\"),\"fieldextraction\",match(source,\"lookups_delete_audit\"),\"lookup\",match(source,\"tags_delete_audit\"),\"tag\"))\n| search type=\"$koType$\"\n```APP NAME: the backup events carry appName directly, but audit events only have the REST URI, so the app has to be pulled out of it at query time. Without this the audit rows have a null appName and the table's app filter silently drops them, which looks like the delete was never captured.```\n| rex field=uri \"\\/en-\\w\\w\\/splunkd\\/__raw\\/servicesNS\\/.*?\\/(?<appName>.+?)\\/\"\n| rex field=uri \"/servicesNS/.*?\\/(?<appName>.*?)/data/ui/views/\"\n| rex field=uri \"/servicesNS/[^/]+/(?<app_uri>[^/]+)/\"\n| rex \"(?<method>updated)\"\n| rex mode=sed field=file \"s/%20/ /g\"\n| rex mode=sed field=file \"s/%3A/:/g\"\n| rex mode=sed field=file \"s/%21/!/g\"\n| rex mode=sed field=file \"s/%28/(/g\"\n| rex mode=sed field=file \"s/%29/)/g\"\n| eval title = coalesce(title,file,dashboard), appName=coalesce(appName,app,app_uri)\n| rex mode=sed field=title \"s/%3A/:/g\"\n| eval ko_format=if(isnotnull(data) AND match(data,\"<definition\"),\"Dashboard Studio\",if(isnotnull(data),\"Simple XML\",\"n/a\"))\n| fields - data\n| table _time updated title type sharing owner user method source description appName ko_format actions action.email.message.alert action.email.to action.email.cc alert.expires alert.severity next_scheduled_time is_scheduled cron_schedule disabled alert_type search label\n| eval time=strftime(_time,\"%F %T\"), history=time.\" - \".method.if(isnotnull(user),\" by \".user,\"\")\n| stats latest(_time) as _time latest(method) as latestMethod latest(sharing) as latestSharing latest(ko_format) as ko_format latest(user) as deletedBy values(*) as * by title appName\n| search title=*\n| table _time updated title type sharing latestSharing owner method latestMethod deletedBy history ko_format source description appName actions action.email.message.alert action.email.to action.email.cc alert.expires alert.severity next_scheduled_time is_scheduled cron_schedule disabled alert_type search label",
        "queryParameters": {
          "earliest": "$tp.earliest$",
          "latest": "$tp.latest$"
        }
      }
    },
    "ds_users": {
      "type": "ds.chain",
      "name": "Filter options - users",
      "options": {
        "extend": "ds_base",
        "query": "| stats c by owner"
      }
    },
    "ds_apps": {
      "type": "ds.chain",
      "name": "Filter options - apps",
      "options": {
        "extend": "ds_base",
        "query": "| search label=\"$searchForDashboard$\" OR title=\"$searchForDashboard$\" owner=\"$selectUser$\"\n| stats c by appName"
      }
    },
    "ds_total": {
      "type": "ds.chain",
      "name": "KPI - total KOs",
      "options": {
        "extend": "ds_base",
        "query": "| search label=\"$searchForDashboard$\" OR title=\"$searchForDashboard$\" appName=\"$selectApp$\" owner=\"$selectUser$\" latestMethod=\"$DeletedToken$\"\n| stats c"
      }
    },
    "ds_top10": {
      "type": "ds.chain",
      "name": "KPI - top 10 apps",
      "options": {
        "extend": "ds_base",
        "query": "| search method!=\"delete\" owner=\"$selectUser$\" latestMethod=\"$DeletedToken$\"\n| chart dc(title) as dc over appName by type\n| addtotals\n| sort 10 - Total\n| fields - Total"
      }
    },
    "ds_deleted": {
      "type": "ds.chain",
      "name": "KPI - deleted count",
      "options": {
        "extend": "ds_base",
        "query": "| search owner=\"$selectUser$\"\n| search latestMethod=\"DELETE\"\n| stats c"
      }
    },
    "ds_apps_kpi": {
      "type": "ds.chain",
      "name": "KPI - distinct apps",
      "options": {
        "extend": "ds_base",
        "query": "| search appName=\"$selectApp$\" owner=\"$selectUser$\"\n| stats dc(appName) as apps"
      }
    },
    "ds_changed7d": {
      "type": "ds.chain",
      "name": "KPI - changed last 7d",
      "options": {
        "extend": "ds_base",
        "query": "| search appName=\"$selectApp$\" owner=\"$selectUser$\"\n| where _time>relative_time(now(),\"-7d\")\n| stats c"
      }
    },
    "ds_private": {
      "type": "ds.chain",
      "name": "KPI - private KOs",
      "options": {
        "extend": "ds_base",
        "query": "| search appName=\"$selectApp$\" owner=\"$selectUser$\"\n| search latestSharing=\"user\"\n| stats c"
      }
    },
    "ds_moved": {
      "type": "ds.chain",
      "name": "KPI - moved count",
      "options": {
        "extend": "ds_base",
        "query": "| search appName=\"$selectApp$\" owner=\"$selectUser$\"\n| search latestMethod=\"MOVE\"\n| stats c"
      }
    },
    "ds_kpi_base": {
      "type": "ds.search",
      "name": "KPI base - backups per KO",
      "options": {
        "query": "index=\"ko_history\" NOT source=\"ko_usage\"\n| eval type=coalesce(type, case(match(source,\"views_delete_audit\"),\"views\",match(source,\"reports_and_alerts_delete_audit\"),\"savedsearch\",match(source,\"macros_delete_audit\"),\"macro\",match(source,\"eventtypes_delete_audit\"),\"eventtype\",match(source,\"fieldextractions_delete_audit\"),\"fieldextraction\",match(source,\"lookups_delete_audit\"),\"lookup\",match(source,\"tags_delete_audit\"),\"tag\"))\n| search type=\"$koType$\"\n| search NOT source=\"*delete_audit*\"\n| eval title=coalesce(title,file), appName=coalesce(appName,app)\n| search appName=\"$selectApp$\" owner=\"$selectUser$\"\n| stats count as v by title appName",
        "queryParameters": {
          "earliest": "$tp.earliest$",
          "latest": "$tp.latest$"
        }
      }
    },
    "ds_versions_kpi": {
      "type": "ds.chain",
      "name": "KPI - versions captured",
      "options": {
        "extend": "ds_kpi_base",
        "query": "| stats sum(v) as c"
      }
    },
    "ds_withhistory": {
      "type": "ds.chain",
      "name": "KPI - KOs with history",
      "options": {
        "extend": "ds_kpi_base",
        "query": "| where v>1\n| stats count"
      }
    },
    "ds_mostchanged": {
      "type": "ds.chain",
      "name": "KPI - most-changed KOs",
      "options": {
        "extend": "ds_kpi_base",
        "query": "| eval title=replace(replace(replace(title,\"%20\",\" \"),\"%3A\",\":\"),\"%21\",\"!\")\n| sort - v\n| head 8\n| rename v as Versions title as KO appName as App\n| table KO App Versions"
      }
    },
    "ds_table": {
      "type": "ds.chain",
      "name": "Main - dashboards table",
      "options": {
        "extend": "ds_base",
        "query": "| search label=\"$searchForDashboard$\" OR title=\"$searchForDashboard$\" appName=\"$selectApp$\" owner=\"$selectUser$\" latestMethod=\"$DeletedToken$\"\n| eval hist_n=mvcount(history), changed7d=if(_time>relative_time(now(),\"-7d\"),1,0)\n| search $kpi_filter$\n| fillnull value=n/a\n| sort - _time\n| eventstats c(history) as count_all by title appName\n| eval _n=mvcount(history)\n| eval _oldest=mvindex(history,_n-1)\n| eval _oldest=if(match(_oldest,\"- updated\"),replace(_oldest,\"updated\",\"created\"),_oldest)\n| eval _counter=if(_n>5,(_n-5).\" more updates\",null())\n| eval history=case(_n=1, _oldest, _n<=5, mvappend(mvindex(history,0,_n-2),_oldest), 1==1, mvappend(mvindex(history,0,3),_counter,_oldest))\n| eval latestMethod=case(count_all=1 AND match(latestMethod,\"updated\"), replace(latestMethod,\"updated\",\"created\"),1==1, latestMethod)\n| fields - count_all _n _oldest _counter\n| eval _rtype=coalesce(type,\"views\")\n| eval _kclass=if(_rtype=\"views\",\"dashboard\",_rtype)\n| eval type=case(type=\"views\" AND ko_format=\"Dashboard Studio\",\"Dashboard (Studio)\",type=\"views\" AND ko_format=\"Simple XML\",\"Dashboard (Simple XML)\",type=\"views\",\"Dashboard\",type=\"savedsearch\",\"Saved search\",type=\"macro\",\"Macro\",type=\"eventtype\",\"Event type\",type=\"fieldextraction\",\"Field extraction\",type=\"lookup\",\"Lookup\",type=\"tag\",\"Tag\",isnotnull(type),type,1==1,\"Dashboard\")\n| eval last_updated=strftime(_time,\"%F %T\")\n| fields - _time\n| table last_updated title type owner appName latestSharing latestMethod deletedBy history _rtype _kclass\n| rename deletedBy as \"By\""
      }
    },
    "ds_table_reports": {
      "type": "ds.chain",
      "name": "Main - reports and alerts table",
      "options": {
        "extend": "ds_base",
        "query": "| search title=\"$searchForDashboard$\" appName=\"$selectApp$\" owner=\"$selectUser$\" latestMethod=\"$DeletedToken$\"\n| eval hist_n=mvcount(history), changed7d=if(_time>relative_time(now(),\"-7d\"),1,0)\n| search $kpi_filter$\n| fillnull value=n/a\n| sort - _time\n| eventstats c(history) as count_all by title appName\n| eval _n=mvcount(history)\n| eval _oldest=mvindex(history,_n-1)\n| eval _oldest=if(match(_oldest,\"- updated\"),replace(_oldest,\"updated\",\"created\"),_oldest)\n| eval _counter=if(_n>5,(_n-5).\" more updates\",null())\n| eval history=case(_n=1, _oldest, _n<=5, mvappend(mvindex(history,0,_n-2),_oldest), 1==1, mvappend(mvindex(history,0,3),_counter,_oldest))\n| eval latestMethod=case(count_all=1 AND match(latestMethod,\"updated\"), replace(latestMethod,\"updated\",\"created\"),1==1, latestMethod)\n| fields - count_all _n _oldest _counter\n| eval _rtype=coalesce(type,\"views\")\n| eval _kclass=if(_rtype=\"views\",\"dashboard\",_rtype)\n| eval scheduled=case(is_scheduled=\"1\",\"Scheduled\",is_scheduled=\"0\",\"Manual\",1==1,\"n/a\")\n| eval kind=case(isnotnull(alert_type) AND alert_type!=\"always\" AND alert_type!=\"n/a\",\"Alert\",scheduled=\"Scheduled\",\"Scheduled report\",1==1,\"Saved search\")\n| eval severity='alert.severity'\n| eval last_updated=strftime(_time,\"%F %T\")\n| fields - _time\n| table last_updated title owner appName latestSharing kind scheduled cron_schedule severity actions latestMethod deletedBy history _rtype _kclass\n| rename deletedBy as \"By\""
      }
    },
    "ds_table_macros": {
      "type": "ds.chain",
      "name": "Main - macros table",
      "options": {
        "extend": "ds_base",
        "query": "| search title=\"$searchForDashboard$\" appName=\"$selectApp$\" owner=\"$selectUser$\" latestMethod=\"$DeletedToken$\"\n| eval hist_n=mvcount(history), changed7d=if(_time>relative_time(now(),\"-7d\"),1,0)\n| search $kpi_filter$\n| fillnull value=n/a\n| sort - _time\n| eventstats c(history) as count_all by title appName\n| eval _n=mvcount(history)\n| eval _oldest=mvindex(history,_n-1)\n| eval _oldest=if(match(_oldest,\"- updated\"),replace(_oldest,\"updated\",\"created\"),_oldest)\n| eval _counter=if(_n>5,(_n-5).\" more updates\",null())\n| eval history=case(_n=1, _oldest, _n<=5, mvappend(mvindex(history,0,_n-2),_oldest), 1==1, mvappend(mvindex(history,0,3),_counter,_oldest))\n| eval latestMethod=case(count_all=1 AND match(latestMethod,\"updated\"), replace(latestMethod,\"updated\",\"created\"),1==1, latestMethod)\n| fields - count_all _n _oldest _counter\n| eval _rtype=coalesce(type,\"views\")\n| eval _kclass=if(_rtype=\"views\",\"dashboard\",_rtype)\n| eval last_updated=strftime(_time,\"%F %T\")\n| fields - _time\n| table last_updated title owner appName latestSharing latestMethod deletedBy history _rtype _kclass\n| rename deletedBy as \"By\""
      }
    },
    "ds_table_eventtypes": {
      "type": "ds.chain",
      "name": "Main - event types table",
      "options": {
        "extend": "ds_base",
        "query": "| search title=\"$searchForDashboard$\" appName=\"$selectApp$\" owner=\"$selectUser$\" latestMethod=\"$DeletedToken$\"\n| eval hist_n=mvcount(history), changed7d=if(_time>relative_time(now(),\"-7d\"),1,0)\n| search $kpi_filter$\n| fillnull value=n/a\n| sort - _time\n| eventstats c(history) as count_all by title appName\n| eval _n=mvcount(history)\n| eval _oldest=mvindex(history,_n-1)\n| eval _oldest=if(match(_oldest,\"- updated\"),replace(_oldest,\"updated\",\"created\"),_oldest)\n| eval _counter=if(_n>5,(_n-5).\" more updates\",null())\n| eval history=case(_n=1, _oldest, _n<=5, mvappend(mvindex(history,0,_n-2),_oldest), 1==1, mvappend(mvindex(history,0,3),_counter,_oldest))\n| eval latestMethod=case(count_all=1 AND match(latestMethod,\"updated\"), replace(latestMethod,\"updated\",\"created\"),1==1, latestMethod)\n| fields - count_all _n _oldest _counter\n| eval _rtype=coalesce(type,\"views\")\n| eval _kclass=if(_rtype=\"views\",\"dashboard\",_rtype)\n| eval last_updated=strftime(_time,\"%F %T\")\n| fields - _time\n| table last_updated title owner appName latestSharing latestMethod deletedBy history _rtype _kclass\n| rename deletedBy as \"By\""
      }
    },
    "ds_table_fieldextractions": {
      "type": "ds.chain",
      "name": "Main - field extractions table",
      "options": {
        "extend": "ds_base",
        "query": "| search title=\"$searchForDashboard$\" appName=\"$selectApp$\" owner=\"$selectUser$\" latestMethod=\"$DeletedToken$\"\n| eval hist_n=mvcount(history), changed7d=if(_time>relative_time(now(),\"-7d\"),1,0)\n| search $kpi_filter$\n| fillnull value=n/a\n| sort - _time\n| eventstats c(history) as count_all by title appName\n| eval _n=mvcount(history)\n| eval _oldest=mvindex(history,_n-1)\n| eval _oldest=if(match(_oldest,\"- updated\"),replace(_oldest,\"updated\",\"created\"),_oldest)\n| eval _counter=if(_n>5,(_n-5).\" more updates\",null())\n| eval history=case(_n=1, _oldest, _n<=5, mvappend(mvindex(history,0,_n-2),_oldest), 1==1, mvappend(mvindex(history,0,3),_counter,_oldest))\n| eval latestMethod=case(count_all=1 AND match(latestMethod,\"updated\"), replace(latestMethod,\"updated\",\"created\"),1==1, latestMethod)\n| fields - count_all _n _oldest _counter\n| eval _rtype=coalesce(type,\"views\")\n| eval _kclass=if(_rtype=\"views\",\"dashboard\",_rtype)\n| eval last_updated=strftime(_time,\"%F %T\")\n| fields - _time\n| table last_updated title owner appName latestSharing latestMethod deletedBy history _rtype _kclass\n| rename deletedBy as \"By\""
      }
    },
    "ds_table_lookups": {
      "type": "ds.chain",
      "name": "Main - lookups table",
      "options": {
        "extend": "ds_base",
        "query": "| search title=\"$searchForDashboard$\" appName=\"$selectApp$\" owner=\"$selectUser$\" latestMethod=\"$DeletedToken$\"\n| eval hist_n=mvcount(history), changed7d=if(_time>relative_time(now(),\"-7d\"),1,0)\n| search $kpi_filter$\n| fillnull value=n/a\n| sort - _time\n| eventstats c(history) as count_all by title appName\n| eval _n=mvcount(history)\n| eval _oldest=mvindex(history,_n-1)\n| eval _oldest=if(match(_oldest,\"- updated\"),replace(_oldest,\"updated\",\"created\"),_oldest)\n| eval _counter=if(_n>5,(_n-5).\" more updates\",null())\n| eval history=case(_n=1, _oldest, _n<=5, mvappend(mvindex(history,0,_n-2),_oldest), 1==1, mvappend(mvindex(history,0,3),_counter,_oldest))\n| eval latestMethod=case(count_all=1 AND match(latestMethod,\"updated\"), replace(latestMethod,\"updated\",\"created\"),1==1, latestMethod)\n| fields - count_all _n _oldest _counter\n| eval _rtype=coalesce(type,\"views\")\n| eval _kclass=if(_rtype=\"views\",\"dashboard\",_rtype)\n| eval last_updated=strftime(_time,\"%F %T\")\n| fields - _time\n| table last_updated title owner appName latestSharing latestMethod deletedBy history _rtype _kclass\n| rename deletedBy as \"By\""
      }
    },
    "ds_table_tags": {
      "type": "ds.chain",
      "name": "Main - tags table",
      "options": {
        "extend": "ds_base",
        "query": "| search title=\"$searchForDashboard$\" appName=\"$selectApp$\" owner=\"$selectUser$\" latestMethod=\"$DeletedToken$\"\n| eval hist_n=mvcount(history), changed7d=if(_time>relative_time(now(),\"-7d\"),1,0)\n| search $kpi_filter$\n| fillnull value=n/a\n| sort - _time\n| eventstats c(history) as count_all by title appName\n| eval _n=mvcount(history)\n| eval _oldest=mvindex(history,_n-1)\n| eval _oldest=if(match(_oldest,\"- updated\"),replace(_oldest,\"updated\",\"created\"),_oldest)\n| eval _counter=if(_n>5,(_n-5).\" more updates\",null())\n| eval history=case(_n=1, _oldest, _n<=5, mvappend(mvindex(history,0,_n-2),_oldest), 1==1, mvappend(mvindex(history,0,3),_counter,_oldest))\n| eval latestMethod=case(count_all=1 AND match(latestMethod,\"updated\"), replace(latestMethod,\"updated\",\"created\"),1==1, latestMethod)\n| fields - count_all _n _oldest _counter\n| eval _rtype=coalesce(type,\"views\")\n| eval _kclass=if(_rtype=\"views\",\"dashboard\",_rtype)\n| eval last_updated=strftime(_time,\"%F %T\")\n| fields - _time\n| table last_updated title owner appName latestSharing latestMethod deletedBy history _rtype _kclass\n| rename deletedBy as \"By\""
      }
    },
    "ds_dataview": {
      "type": "ds.search",
      "name": "Drilldown - raw source by title",
      "options": {
        "query": "index=\"ko_history\" NOT source=\"ko_usage\" title=\"$drilldownTitle$\"\n| eval appName=coalesce(appName,app)\n| where type=\"$ko_realtype$\" AND appName=\"$link_app$\"\n| rex mode=sed \"s/^.*?data=\\\"//\"\n| rex mode=sed \"s/\\\", type=views[\\s\\S]*//\"\n| eval _raw=replace(_raw,\"\\\\\\\\(.)\",\"\\1\")\n| table _time _raw label\n| sort - _time",
        "queryParameters": {
          "earliest": "$tp.earliest$",
          "latest": "$tp.latest$"
        }
      }
    },
    "ds_versions": {
      "type": "ds.chain",
      "name": "Drilldown - version list",
      "options": {
        "extend": "ds_dataview",
        "query": "| eval _epoch=_time\n| streamstats count as vn\n| eval version_no=if(vn=1,\"#\".vn.\" (latest)\",\"#\".vn)\n| eval version_time=strftime(_time,\"%F %T\")\n| eval ko_format=if(match(_raw,\"<definition\"),\"Dashboard Studio\",\"Simple XML\")\n| fillnull value=\"\u2013\" label\n| fields version_no version_time label ko_format _epoch\n| fields - _time"
      }
    },
    "ds_version_pick": {
      "type": "ds.chain",
      "name": "Drilldown - version picker options",
      "options": {
        "extend": "ds_versions",
        "query": "| eval pick_label=version_no . \"  \" . version_time\n| table pick_label _epoch\n| head 200"
      }
    },
    "ds_versions_ss": {
      "type": "ds.search",
      "name": "Drilldown - saved-search version list",
      "options": {
        "query": "index=\"ko_history\" NOT source=\"ko_usage\" title=\"$drilldownTitle$\"\n| eval appName=coalesce(appName,app)\n| where type=\"$ko_realtype$\" AND appName=\"$link_app$\"\n| sort - _time\n| streamstats count as vn\n| eval version_no=if(vn=1,\"#\".vn.\" (latest)\",\"#\".vn)\n| eval version_time=strftime(_time,\"%F %T\")\n| eval _epoch=_time\n| eval _audit=if(isnull('search') OR 'search'=\"\",1,0)\n| eval schedule=case(_audit=1,\"\u2013\", 'is_scheduled'=1,coalesce(cron_schedule,\"\u2013\"), true(),\"Not scheduled\")\n| eval state=case(_audit=1,upper(coalesce(method,\"change\")), disabled=1,\"Disabled\", true(),\"Enabled\")\n| eval actions=case(_audit=1,\"\u2013\", isnull(actions) OR actions=\"\",\"\u2013\", true(),actions)\n| fields version_no version_time schedule state actions _epoch\n| fields - _time",
        "queryParameters": {
          "earliest": "$tp.earliest$",
          "latest": "$tp.latest$"
        }
      }
    },
    "ds_versions_generic": {
      "type": "ds.search",
      "name": "Drilldown - generic KO version list",
      "options": {
        "query": "index=\"ko_history\" NOT source=\"ko_usage\" title=\"$drilldownTitle$\"\n| eval appName=coalesce(appName,app)\n| where type=\"$ko_realtype$\" AND appName=\"$link_app$\"\n| eval _content=coalesce(definition,search,regex,value,eval,template)\n| sort - _time\n| streamstats count as vn\n| eval version_no=if(vn=1,\"#\".vn.\" (latest)\",\"#\".vn)\n| eval version_time=strftime(_time,\"%F %T\")\n| eval _epoch=_time\n| eval _audit=if(isnull(_content) OR _content=\"\",1,0)\n| eval state=case(_audit=1,upper(coalesce(method,\"change\")), true(),\"Updated\")\n| fields version_no version_time state _epoch\n| fields - _time",
        "queryParameters": {
          "earliest": "$tp.earliest$",
          "latest": "$tp.latest$"
        }
      }
    },
    "ds_timeline": {
      "type": "ds.search",
      "name": "Drilldown - KO action timeline",
      "options": {
        "query": "index=\"ko_history\" NOT source=\"ko_usage\"\n| eval type=coalesce(type, case(match(source,\"views_delete_audit\"),\"views\",match(source,\"reports_and_alerts_delete_audit\"),\"savedsearch\",match(source,\"macros_delete_audit\"),\"macro\",match(source,\"eventtypes_delete_audit\"),\"eventtype\",match(source,\"fieldextractions_delete_audit\"),\"fieldextraction\",match(source,\"lookups_delete_audit\"),\"lookup\",match(source,\"tags_delete_audit\"),\"tag\"))\n| rex field=uri \"/servicesNS/[^/]+/(?<app_uri>[^/]+)/\"\n| rex mode=sed field=file \"s/%20/ /g\"\n| rex mode=sed field=file \"s/%3A/:/g\"\n| rex mode=sed field=file \"s/%21/!/g\"\n| rex mode=sed field=file \"s/%28/(/g\"\n| rex mode=sed field=file \"s/%29/)/g\"\n| eval title=coalesce(title,file,dashboard), appName=coalesce(appName,app,app_uri)\n| rex mode=sed field=title \"s/%3A/:/g\"\n| where title=\"$drilldownTitle$\" AND type=\"$ko_realtype$\" AND appName=\"$link_app$\"\n| eval action=case(match(method,\"(?i)delete\"),\"deleted\",match(method,\"(?i)move\"),\"moved\",1==1,\"updated\")\n| sort 0 _time\n| streamstats count as _n\n| eval action=if(_n=1 AND action=\"updated\",\"created\",action)\n| timechart count by action\n",
        "queryParameters": {
          "earliest": "$tp.earliest$",
          "latest": "$tp.latest$"
        }
      }
    },
    "ds_source": {
      "type": "ds.chain",
      "name": "Drilldown - selected vs previous source",
      "options": {
        "extend": "ds_dataview",
        "query": "| eval _sel=tonumber(\"0\" . replace(\"$time$\",\"[^0-9]\",\"\"))\n| eval _new=tonumber(\"0\" . replace(\"$compare_newer$\",\"[^0-9]\",\"\"))\n| eval _old=tonumber(\"0\" . replace(\"$compare_older$\",\"[^0-9]\",\"\"))\n| eval _pick=if(_new>0 AND _old>0,1,0)\n| where _pick=0 OR _time=_new OR _time=_old\n| where _pick=1 OR _sel=0 OR _time<=_sel\n| sort - _time\n| head 2\n| streamstats count as _rn\n| eval role=if(_rn=1,\"target\",\"baseline\")\n| eval data=_raw, title=\"$drilldownTitle$\", app=\"$link_app$\"\n| table role title app data"
      }
    },
    "ds_report_card": {
      "type": "ds.search",
      "name": "Drilldown - generic KO record fields",
      "options": {
        "query": "index=\"ko_history\" NOT source=\"ko_usage\" title=\"$drilldownTitle$\"\n| eval appName=coalesce(appName,app)\n| where type=\"$ko_realtype$\" AND appName=\"$link_app$\"\n| where NOT match(source,\"_delete_audit$\")\n| eval _sel=tonumber(\"0\" . replace(\"$time$\",\"[^0-9]\",\"\"))\n| eval _new=tonumber(\"0\" . replace(\"$compare_newer$\",\"[^0-9]\",\"\"))\n| eval _old=tonumber(\"0\" . replace(\"$compare_older$\",\"[^0-9]\",\"\"))\n| eval _pick=if(_new>0 AND _old>0,1,0)\n| where _pick=0 OR _time=_new OR _time=_old\n| where _pick=1 OR _sel=0 OR _time<=_sel\n| sort - _time\n| head 2\n| streamstats count as _rn\n| eval role=if(_rn=1,\"target\",\"baseline\")\n| table role title appName owner sharing type updated disabled is_scheduled is_visible definition args iseval priority tags color value extract_kind attribute stanza filename lookup_type collection external_cmd fields_list case_sensitive_match alert_type description search dispatch.earliest_time dispatch.latest_time cron_schedule realtime_schedule next_scheduled_time schedule_window schedule_priority actions action.email.to action.email.cc action.email.bcc action.email.from action.email.subject action.email.message.alert action.email.sendresults action.email.inline action.script.filename action.webhook.param.url action.summary_index._name action.summary_index.* alert_comparator alert_threshold alert_condition alert.severity alert.expires alert.track alert.digest_mode alert.suppress alert.suppress.fields alert.suppress.period",
        "queryParameters": {
          "earliest": "$tp.earliest$",
          "latest": "$tp.latest$"
        }
      }
    },
    "ds_open": {
      "type": "ds.search",
      "name": "Drilldown - open live KO link",
      "options": {
        "query": "| makeresults count=1\n| eval label=\"\u2197  Open \\\"$link_title$\\\" in a new browser tab\"\n| fields - _time\n| table label"
      }
    }
  },
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time",
      "options": {
        "token": "tp",
        "defaultValue": "0,"
      }
    },
    "input_user": {
      "type": "input.dropdown",
      "title": "Select User",
      "dataSources": {
        "primary": "ds_users"
      },
      "options": {
        "items": [
          {
            "label": "All",
            "value": "*"
          }
        ],
        "defaultValue": "*",
        "token": "selectUser"
      },
      "encoding": {
        "label": "primary.owner",
        "value": "primary.owner"
      }
    },
    "input_search": {
      "type": "input.text",
      "title": "Search label/title",
      "options": {
        "defaultValue": "*",
        "token": "searchForDashboard"
      }
    },
    "input_compare_newer": {
      "type": "input.dropdown",
      "title": "Compare this version",
      "dataSources": {
        "primary": "ds_version_pick"
      },
      "options": {
        "items": [
          {
            "label": "Auto: the version you clicked",
            "value": "auto"
          }
        ],
        "defaultValue": "auto",
        "token": "compare_newer"
      },
      "encoding": {
        "label": "primary.pick_label",
        "value": "primary._epoch"
      },
      "containerOptions": {
        "visibility": {
          "showConditions": [
